const upsertAppGovernance = `-- name: UpsertAppGovernance :exec
INSERT INTO app_governance (app_id, approved_version, approved_risk, ever_approved)
VALUES ($1, $2, $3, $4)
ON CONFLICT (app_id) DO UPDATE
SET approved_version = EXCLUDED.approved_version,
    approved_risk = EXCLUDED.approved_risk,
    ever_approved = app_governance.ever_approved OR EXCLUDED.ever_approved
`

type UpsertAppGovernanceParams struct {
	AppID           int64       `json:"app_id"`
	ApprovedVersion pgtype.Int4 `json:"approved_version"`
	ApprovedRisk    []byte      `json:"approved_risk"`
	EverApproved    bool        `json:"ever_approved"`
}

func (q *Queries) UpsertAppGovernance(ctx context.Context, arg UpsertAppGovernanceParams) error {
	_, err := q.db.Exec(ctx, upsertAppGovernance,
		arg.AppID,
		arg.ApprovedVersion,
		arg.ApprovedRisk,
		arg.EverApproved,
	)
	return err
}

const versionWasApproved = `-- name: VersionWasApproved :one
SELECT EXISTS (SELECT 1 FROM approval_requests WHERE app_id = $1 AND app_version = $2 AND status IN ('approved', 'auto'))
`

type VersionWasApprovedParams struct {
	AppID      pgtype.Int8 `json:"app_id"`
	AppVersion pgtype.Int4 `json:"app_version"`
}

func (q *Queries) VersionWasApproved(ctx context.Context, arg VersionWasApprovedParams) (bool, error) {
	row := q.db.QueryRow(ctx, versionWasApproved, arg.AppID, arg.AppVersion)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
